-- Admission Checklist & Contacts tab content
INSERT INTO page_sections (section_key, html_content, updated_at)
VALUES ('admission-checklist', $ADMCHK$<style>
.ac-contact-grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(260px,1fr)); gap:14px; margin-top:8px; }
.ac-contact-card { background:var(--card-bg); border:1.5px solid var(--border); border-radius:12px; padding:14px 16px; }
.ac-c-dept { font-size:13px; font-weight:700; color:var(--text); margin-bottom:10px; }
.ac-c-people { display:flex; flex-wrap:wrap; gap:12px; margin-bottom:10px; }
.ac-person { display:flex; align-items:center; gap:8px; font-size:12px; color:var(--text); }
.ac-c-row { font-size:11.5px; color:var(--text-muted,#888); line-height:1.6; }
.ac-c-row a { color:#378ADD; text-decoration:none; }
.ac-c-row a:hover { text-decoration:underline; }
.ac-section-head { display:flex; align-items:center; justify-content:space-between; margin:22px 0 4px; }
.ac-section-head:first-child { margin-top:0; }
.ac-pill { font-size:11px; font-weight:700; padding:3px 11px; border-radius:20px; background:var(--bg,#f4f4f4); border:1px solid var(--border); color:var(--text-muted,#888); }
</style>

<div class="section-title">📋 Hof Enrollment Checklist &amp; Contacts</div>
<div class="section-sub">Everything from your Kick-Off, IT Systems, and Administrative Steps orientation packs — tick items off as you complete them.</div>

<div class="ac-section-head"><strong style="font-size:14px;">✈️ Before You Fly <span style="font-weight:400;color:var(--text-muted,#888);">(now – Oct 3)</span></strong><span class="ac-pill" id="admchk-prefly-count">0/7</span></div>
<div class="cl-item cl-important">
  <input type="checkbox" class="cl-check persist-check" id="admission-checklist-prefly-moodle" onchange="saveCheck(this); updateAdmissionChecklistProgress();">
  <div class="cl-body">
    <label class="cl-label" for="admission-checklist-prefly-moodle">Join the Moodle Welcome Center room — log in at <a href="https://moodle.hof-university.de/" target="_blank">moodle.hof-university.de</a> via Shibboleth, join course id 643 with enrollment key <strong>WelcomeToHof</strong>, and select your study program (<strong>SE-WS26</strong>).</label>
    
  </div>
  <span class="cl-chip chip-important">Important</span>
</div><div class="cl-item cl-critical">
  <input type="checkbox" class="cl-check persist-check" id="admission-checklist-prefly-primuss-cert" onchange="saveCheck(this); updateAdmissionChecklistProgress();">
  <div class="cl-body">
    <label class="cl-label" for="admission-checklist-prefly-primuss-cert">Download your enrollment certificate ("Immatrikulationsbescheinigung") from the <a href="https://www3.primuss.de/cgi-bin/login/index.pl?FH=fhh" target="_blank">Primuss student portal</a> — needed for health insurance, bank account, and immigration office.</label>
    
  </div>
  <span class="cl-chip chip-critical">Critical</span>
</div><div class="cl-item cl-important">
  <input type="checkbox" class="cl-check persist-check" id="admission-checklist-prefly-arrival-form" onchange="saveCheck(this); updateAdmissionChecklistProgress();">
  <div class="cl-body">
    <label class="cl-label" for="admission-checklist-prefly-arrival-form">Confirm your arrival date via the <a href="https://www.hof-university.com/studying-at-hof-university/services-and-support/housing/arrival-form.html" target="_blank">arrival form</a> so the International Student Network invites you to events.</label>
    
  </div>
  <span class="cl-chip chip-important">Important</span>
</div><div class="cl-item cl-optional">
  <input type="checkbox" class="cl-check persist-check" id="admission-checklist-prefly-community" onchange="saveCheck(this); updateAdmissionChecklistProgress();">
  <div class="cl-body">
    <label class="cl-label" for="admission-checklist-prefly-community">Join the <a href="https://chat.whatsapp.com/LswYgVJygZB7HTyzi9PZ6L?s=cl&p=i&mlu=4" target="_blank">WhatsApp group</a> for WS26 international students and follow <a href="https://www.instagram.com/hof.university.international/" target="_blank">Instagram</a>.</label>
    
  </div>
  <span class="cl-chip chip-optional">Optional</span>
</div><div class="cl-item cl-critical">
  <input type="checkbox" class="cl-check persist-check" id="admission-checklist-prefly-orientation" onchange="saveCheck(this); updateAdmissionChecklistProgress();">
  <div class="cl-body">
    <label class="cl-label" for="admission-checklist-prefly-orientation">Attend orientation online — Academic Writing &amp; Learning Culture (mandatory, Mon Sept 28, via Zoom link in moodle "Orientation Week"). Time-management workshop optional — <a href="https://terminplaner6.dfn.de/de/b/63e2973c502a23f88fda898d49b81a5b-1097638" target="_blank">register here</a>.</label>
    
  </div>
  <span class="cl-chip chip-critical">Critical</span>
</div><div class="cl-item cl-critical">
  <input type="checkbox" class="cl-check persist-check" id="admission-checklist-prefly-health-insurance" onchange="saveCheck(this); updateAdmissionChecklistProgress();">
  <div class="cl-body">
    <label class="cl-label" for="admission-checklist-prefly-health-insurance">Finalize health insurance — get it activated with your enrollment certificate (studying insurance, not travel insurance).</label>
    
  </div>
  <span class="cl-chip chip-critical">Critical</span>
</div><div class="cl-item cl-important">
  <input type="checkbox" class="cl-check persist-check" id="admission-checklist-prefly-blocked-account" onchange="saveCheck(this); updateAdmissionChecklistProgress();">
  <div class="cl-body">
    <label class="cl-label" for="admission-checklist-prefly-blocked-account">Prep blocked account paperwork — check with your provider (Coracle / Fintiba / Expatrio / Sparkasse) if anything is needed before you land.</label>
    
  </div>
  <span class="cl-chip chip-important">Important</span>
</div>

<div class="ac-section-head"><strong style="font-size:14px;">🏠 After You Land in Hof <span style="font-weight:400;color:var(--text-muted,#888);">(from Oct 4)</span></strong><span class="ac-pill" id="admchk-arrival-count">0/8</span></div>
<div class="cl-item cl-critical">
  <input type="checkbox" class="cl-check persist-check" id="admission-checklist-arrival-mailbox" onchange="saveCheck(this); updateAdmissionChecklistProgress();">
  <div class="cl-body">
    <label class="cl-label" for="admission-checklist-arrival-mailbox">Put your full name on the mailbox immediately — city registration, health insurance, and social security letters arrive by post.</label>
    
  </div>
  <span class="cl-chip chip-critical">Critical</span>
</div><div class="cl-item cl-critical">
  <input type="checkbox" class="cl-check persist-check" id="admission-checklist-arrival-cityreg" onchange="saveCheck(this); updateAdmissionChecklistProgress();">
  <div class="cl-body">
    <label class="cl-label" for="admission-checklist-arrival-cityreg">Register your address with the city within 14 days — <a href="https://kurzlinks.de/residence" target="_blank">kurzlinks.de/residence</a> if in Hof (fully online). Other cities: email their registration office directly.</label>
    
  </div>
  <span class="cl-chip chip-critical">Critical</span>
</div><div class="cl-item cl-critical">
  <input type="checkbox" class="cl-check persist-check" id="admission-checklist-arrival-bank" onchange="saveCheck(this); updateAdmissionChecklistProgress();">
  <div class="cl-body">
    <label class="cl-label" for="admission-checklist-arrival-bank">Open a German current account (Girokonto) — Hof partners with <a href="https://www.sparkasse-hochfranken.de/giro-student" target="_blank">Sparkasse Hochfranken</a>. Bring passport, Meldebescheinigung, enrollment certificate. Kotak accounts aren't recognized in Germany — open a German blocked account too if that applies. Legitimate in person within 7 days.</label>
    
  </div>
  <span class="cl-chip chip-critical">Critical</span>
</div><div class="cl-item cl-critical">
  <input type="checkbox" class="cl-check persist-check" id="admission-checklist-arrival-blocked-activate" onchange="saveCheck(this); updateAdmissionChecklistProgress();">
  <div class="cl-body">
    <label class="cl-label" for="admission-checklist-arrival-blocked-activate">Activate your blocked account once your current account and city registration are ready, via your provider's online form.</label>
    
  </div>
  <span class="cl-chip chip-critical">Critical</span>
</div><div class="cl-item cl-important">
  <input type="checkbox" class="cl-check persist-check" id="admission-checklist-arrival-campuscard" onchange="saveCheck(this); updateAdmissionChecklistProgress();">
  <div class="cl-body">
    <label class="cl-label" for="admission-checklist-arrival-campuscard">Collect and validate your CampusCard at student affairs (room A111 — Mon/Thu 12-3pm, Tue/Wed/Fri 9am-12pm). Allocate at the blue terminal, validate near A115, sign the back, load money on it.</label>
    
  </div>
  <span class="cl-chip chip-important">Important</span>
</div><div class="cl-item cl-important">
  <input type="checkbox" class="cl-check persist-check" id="admission-checklist-arrival-residence-permit" onchange="saveCheck(this); updateAdmissionChecklistProgress();">
  <div class="cl-body">
    <label class="cl-label" for="admission-checklist-arrival-residence-permit">Apply for your residence permit — only 6-8 weeks before your visa expires (10+ weeks if travelling abroad soon after). Email Ms. Schaller at <a href="mailto:rebecca.schaller@stadt-hof.de">rebecca.schaller@stadt-hof.de</a>.</label>
    
  </div>
  <span class="cl-chip chip-important">Important</span>
</div><div class="cl-item cl-important">
  <input type="checkbox" class="cl-check persist-check" id="admission-checklist-arrival-primuss-address" onchange="saveCheck(this); updateAdmissionChecklistProgress();">
  <div class="cl-body">
    <label class="cl-label" for="admission-checklist-arrival-primuss-address">Update your address in PRIMUSS once you have your German address.</label>
    
  </div>
  <span class="cl-chip chip-important">Important</span>
</div><div class="cl-item cl-optional">
  <input type="checkbox" class="cl-check persist-check" id="admission-checklist-arrival-scam-awareness" onchange="saveCheck(this); updateAdmissionChecklistProgress();">
  <div class="cl-body">
    <label class="cl-label" for="admission-checklist-arrival-scam-awareness">Stay alert to phone scams — German authorities never ask for sensitive data by phone.</label>
    
  </div>
  <span class="cl-chip chip-optional">Optional</span>
</div>

