<script>
function updateAdmissionChecklistProgress() {
  var preflyIds = ["'admission-checklist-prefly-moodle'", "'admission-checklist-prefly-primuss-cert'", "'admission-checklist-prefly-arrival-form'", "'admission-checklist-prefly-community'", "'admission-checklist-prefly-orientation'", "'admission-checklist-prefly-health-insurance'", "'admission-checklist-prefly-blocked-account'"];
  var arrivalIds = ["'admission-checklist-arrival-mailbox'", "'admission-checklist-arrival-cityreg'", "'admission-checklist-arrival-bank'", "'admission-checklist-arrival-blocked-activate'", "'admission-checklist-arrival-campuscard'", "'admission-checklist-arrival-residence-permit'", "'admission-checklist-arrival-primuss-address'", "'admission-checklist-arrival-scam-awareness'"];
  function countChecked(ids) {
    var n = 0;
    ids.forEach(function(id) { var el = document.getElementById(id); if (el && el.checked) n++; });
    return n;
  }
  var pf = document.getElementById('admchk-prefly-count');
  var af = document.getElementById('admchk-arrival-count');
  if (pf) pf.textContent = countChecked(preflyIds) + '/' + preflyIds.length;
  if (af) af.textContent = countChecked(arrivalIds) + '/' + arrivalIds.length;
}
setTimeout(updateAdmissionChecklistProgress, 300);
</script>
$ADMCHK$, now())
ON CONFLICT (section_key) DO UPDATE SET html_content = EXCLUDED.html_content, updated_at = EXCLUDED.updated_at;
